// Access the aggregated array of destinations
const aggregatedData = $input.first().json.data;
const allValidFlights = [];

// Safety check in case the data is missing
if (!aggregatedData || !Array.isArray(aggregatedData)) {
  return [];
}

// --- DICTIONARIES ---

// 1. Month Mapping
const monthMap = {
  "Jan": "01", "Feb": "02", "Mar": "03", "Apr": "04", "May": "05", "Jun": "06",
  "Jul": "07", "Aug": "08", "Sep": "09", "Oct": "10", "Nov": "11", "Dec": "12"
};

// 2. City to IATA Sector Mapping
const iataMap = {
  "COCHIN": "COK", "CALICUT": "CCJ", "KANNUR": "CNN", "TRIVANDRUM": "TRV",
  "MANGALORE": "IXE", "COLOMBO": "CMB", "LUCKNOW": "LKO", "DOHA": "DOH",
  "ABUDHABI": "AUH", "SHARJAH": "SHJ", "DUBAI": "DXB", "JEDDAH": "JED",
  "RIYADH": "RUH", "DAMMAM": "DMM", "RAS AL KHAIMAH": "RKT", "MUSCAT": "MCT",
  "KUWAIT": "KWI", "FUJAIRAH": "FJR", "KUALA LUMPUR": "KUL"
};

// 3. Image Name to 2-Letter Airline Code Mapping
const airlineMap = {
  "AIR INDIA": "AI", "INDIGO": "6E", "AKASAAIR": "QP", "SALAMAIR": "OV",
  "SRILANKA": "UL", "JAZEERA": "J9", "FLYDUBAI": "FZ", "SOUDIA": "SV",
  "SAUDIA": "SV", "FLYNAS": "XY", "AIRASIA": "AK", "AIR ARABIA": "G9",
  "AIR EXPRESS": "IX", "AIR INDIA EXPRESS": "IX", "SPICEJET": "SG"
};

// 4. Default Baggage Fallbacks (if scraped baggage is empty)
const defaultBaggage = {
  "IX": { bag: "30", extra: "7" }, "6E": { bag: "30", extra: "7" },
  "G9": { bag: "30", extra: "10" }, "XY": { bag: "30", extra: "7" },
  "WY": { bag: "30", extra: "7" }, "OV": { bag: "20", extra: "5" },
  "AI": { bag: "30", extra: "7" }, "SV": { bag: "20", extra: "7" },
  "QP": { bag: "30", extra: "7" }, "FZ": { bag: "30", extra: "7" },
  "J9": { bag: "30", extra: "7" }, "SG": { bag: "30", extra: "7" },
  "UL": { bag: "30", extra: "7" }, "AK": { bag: "20", extra: "7" }
};

// --- PROCESSING LOOP ---

// Loop through each destination's block of data
for (const data of aggregatedData) {
  const numFlights = data.Price ? data.Price.length : 0;

  for (let i = 0; i < numFlights; i++) {
    // 1. Clean the Airline Name & Get 2-Letter Code
    let rawSrc = data.AirlineSrc[i] || "";
    let airlineName = rawSrc.split('/').pop().replace(/\.[^/.]+$/, "").trim().toUpperCase();
    let flightCode = airlineMap[airlineName] || airlineName; // Fallback to raw name if missing from map

    // 2. Format the Date (Target: YYYY-MM-DD)
    let day = data.DateDay[i] ? data.DateDay[i].trim() : "";
    if (day.length === 1) day = "0" + day; 
    let monthRaw = data.DateMonthYear[i * 2] ? data.DateMonthYear[i * 2].trim() : "";
    let month = monthMap[monthRaw.substring(0, 3)] || monthRaw;
    let year = data.DateMonthYear[(i * 2) + 1] ? data.DateMonthYear[(i * 2) + 1].trim() : "";
    let fullDate = (year && month && day) ? `${year}-${month}-${day}` : "";

    // 3. Clean Departure/Arrival Times
    let dep = data.DepTime[i] ? data.DepTime[i].replace('Dep-', '').trim() : "";
    let arr = data.ArrTime[i] ? data.ArrTime[i].replace('Arr-', '').trim() : "";

    // 4. Check for Excluded Sectors & Create Sector Code
    let originRaw = data.Origin[i] ? data.Origin[i].trim().toUpperCase() : "";
    let destRaw = data.Destination[i] ? data.Destination[i].trim().toUpperCase() : "";

    // EXCLUSION FILTER: List of sectors to remove (Full names & standard codes)
    const excludedSectors = [
      "AHMEDABAD", "AMD", 
      "LUCKNOW", "LKO", 
      "VARANASI", "VNS", 
      "DELHI", "DEL", 
      "KUALA LUMPUR", "KUL"
    ];

    // Skip this flight if the origin or destination matches the excluded list
    if (excludedSectors.includes(originRaw) || excludedSectors.includes(destRaw)) {
      continue; 
    }

    let originCode = iataMap[originRaw] || originRaw;
    let destCode = iataMap[destRaw] || destRaw;
    let sectorCode = (originCode && destCode) ? `${originCode} ${destCode}` : "";

    // 5. Clean Price. Commission and the final selling price are derived
    // server-side from agents.commission (ingestFaresFromN8n) rather than
    // hardcoded here — sending them in the payload would silently override
    // that and go stale the next time the commission changes in the dashboard.
    let rawPrice = data.Price[i] ? data.Price[i].trim() : "";
    let spRateNum = Number(rawPrice.replace(/[^0-9.]/g, '')) || 0;

    // 6. Parse Baggage (Smarter Split Logic)
    let rawLuggage = data.Luggage[i] ? data.Luggage[i].trim().toUpperCase() : "";
    let parsedBaggage = "";
    let parsedExtra = "";

    // Remove "LUGGAGE" word and leading hyphens/spaces
    let cleanLuggage = rawLuggage.replace(/LUGGAGE/g, '').replace(/^[-\s:]+/, '').trim();
    let lugParts = cleanLuggage.split('-'); // Splits into ["20*2", "5 KG"] etc.

    if (lugParts.length >= 1) {
      let mainPart = lugParts[0];

      // Calculate math like 20*2
      if (mainPart.includes("20*2") || mainPart.includes("20 * 2")) {
        parsedBaggage = "40";
      } else if (mainPart.includes("30*2") || mainPart.includes("30 * 2")) {
        parsedBaggage = "60";
      } else if (mainPart.includes("2PC") || mainPart.includes("2 PC")) {
        let num = mainPart.match(/\d{2,}/);
        parsedBaggage = num ? num[0] : "40"; // Prioritize explicit weight if given (e.g. 40 KG 2 PC)
      } else if (mainPart.includes("1PC") || mainPart.includes("1 PC")) {
        let num = mainPart.match(/\d{2,}/);
        parsedBaggage = num ? num[0] : "20";
      } else {
        // Just extract the first number it finds
        let match = mainPart.match(/\d+/);
        if (match) parsedBaggage = match[0];
      }
    }

    if (lugParts.length >= 2) {
      let extraPart = lugParts[1];
      let match = extraPart.match(/\d+/);
      if (match) {
        parsedExtra = parseInt(match[0], 10).toString(); // Converts "07" into "7"

        // Failsafe: Hand baggage over 15kg is definitely a typo (like "30 - 30")
        if (parseInt(parsedExtra, 10) > 15) {
          parsedExtra = ""; // Clear it so dictionary handles it below
        }
      }
    }

    // Apply default baggage if parsing failed or hit the failsafe
    if (!parsedBaggage && defaultBaggage[flightCode]) {
        parsedBaggage = defaultBaggage[flightCode].bag;
    }
    if (!parsedExtra && defaultBaggage[flightCode]) {
        parsedExtra = defaultBaggage[flightCode].extra;
    }

    // 7. Validate and push to array matching the Firebase schema
    if (sectorCode && fullDate && spRateNum) {
      allValidFlights.push({
        agent_id: 27,
        sector_code: sectorCode,
        date: fullDate,
        time_start: dep,
        time_end: arr,
        flight_code: flightCode, 
        baggage: parsedBaggage,
        extra_baggage: parsedExtra,
        sp_rate: spRateNum,
        show: "yes"
      });
    }
  }
}

// Stop workflow if no valid data was found
if (allValidFlights.length === 0) {
  return []; 
}

// Return ONE single item containing all formatted flights
return [{
  json: {
    firebaseData: allValidFlights
  }
}];

// List of all destinations from the board, excluding KUL
const destinations = [
  "DOH", "AUH", "SHJ", "DXB", 
  "CCJ", "JED", "RUH", "MCT", 
  "COK", "DMM", "RKT", 
  "KWI", "FJR"
];

// Map them into n8n's item structure so it processes them one by one
return destinations.map(dest => {
  return {
    json: {
      destination: dest
    }
  };
});
